import React from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import Login from "./components/login";
import Signup from "./components/signup";
import Home from "./components/home";
import PrivateRoute from "./components/PrivateRoute"; //  This is your ProtectedRoute
import Layout from "./components/Layout";
import "./components/sidebar.css"; //  
import PublicRoute from "./components/PublicRoute"; // import PublicRoute

function App() {
  const token = localStorage.getItem("token"); //  Token check

  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={
          <Layout>
            <Signup />
          </Layout>
        } />
        <Route path="/login" element={
          <Layout>
            <PublicRoute>
              <Login />
            </PublicRoute>
          </Layout>
        } />
        <Route path="/signup" element={
          <Layout>
            <PublicRoute>
              <Signup />
            </PublicRoute>
          </Layout>
        } />

        {/*  Protected home route (renamed from /brands to /home) */}
        <Route
          path="/home"
          element={
            <Layout>
              <PrivateRoute>
                {/* If you have Layout.js, wrap like <Layout><Home /></Layout> */}
                <Home />
              </PrivateRoute>
            </Layout>
          }
        />

        {/*  Catch-all route using token for redirection */}
        <Route
          path="*"
          element={<Navigate to={token ? "/home" : "/login"} replace />}
        />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
